import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"802.11 帧与 OFDM","description":"","frontmatter":{"title":"802.11 帧与 OFDM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wifi-frames-ofdm.md","filePath":"cs/wifi-frames-ofdm.md","lastUpdated":1789023840000}'),c={name:"cs/wifi-frames-ofdm.md"};function C(h,a,m,M,D,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="_802-11-帧与-ofdm" tabindex="-1">802.11 帧与 OFDM <a class="header-anchor" href="#_802-11-帧与-ofdm" aria-label="Permalink to &quot;802.11 帧与 OFDM&quot;">​</a></h1><div class="epigraph"><p>无线没有可靠的载波碰撞检测，帧要带时长预约；OFDM 把宽带切成许多正交子载波，对抗频率选择性衰落。</p><footer>—— 据 IEEE 802.11；Weinstein and Ebert, OFDM, IEEE Trans. Commun. 1971；Kurose and Ross 无线章整理</footer></div><p>上一课序在<a href="/cs/output-queue-hol">输出排队与 HOL</a> 收束有线交换。主干<a href="/cs/csma-ca">CSMA/CA</a> 已给过退避。缺口是<strong>帧怎么占空中、物理层怎么占频谱</strong>：802.11 MAC 头、NAV、ACK；PHY 从 DSSS 走到 OFDM。本课不把 MIMO 矩阵写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>以太网全双工点到点几乎不冲突；无线是半双工共享介质，隐终端让 CD 不可靠，故 CA + RTS/CTS 预约。帧：帧控制、地址（可到四个，因为有 DS）、序号、FCS。数据帧后 SIFS 跟 ACK，失败才重传——这是链路努力，不是 TCP 的替代。OFDM：高 \\(R_s\\) 在多径下 ISI 严重，改用慢符号率的多子载波，循环前缀吃掉时延扩展。容量仍是 \\(B\\) 与 SNR，只是 \\(B\\) 被切成子信道。</p><p><span class="marginnote">802.11a/g/n/ac 的 PHY 都以 OFDM 为骨干。地址字段服务基础设施 BSS：AP 与 DS。本课不把每个 subtype 背完。</span></p><h3 id="无线-ack-不取消-tcp" tabindex="-1">无线 ACK 不取消 TCP <a class="header-anchor" href="#无线-ack-不取消-tcp" aria-label="Permalink to &quot;无线 ACK 不取消 TCP&quot;">​</a></h3><p>CA 补不能可靠 CD。OFDM 用多子载波抗多径。MCS 阶梯是离散工作点，瞬时 \\(C\\) 随衰落变。AP 桥到有线，不是全国洪泛。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：DCF 听信道 → 发 → ACK；并行画：比特 → 编码交织 → 映到子载波 → IFFT → 加 CP。对照有线 PAM：无线必须估计每子载波信道。速率集（6–54 Mb/s 等）是调制编码方案，下一课自适应。</p>',10)),(e(),n(p,null,{default:r(()=>[A(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22802.11%20MAC%20%E5%B8%A7%22%5D%20--%3E%20CSMA%5B%22CSMA%2FCA%20%E4%B8%8E%20NAV%22%5D%0A%20%20MAC%20--%3E%20OFDM%5B%22%E5%AD%90%E8%BD%BD%E6%B3%A2%E6%98%A0%E5%B0%84%22%5D%0A%20%20OFDM%20--%3E%20AIR%5B%22%E7%A9%BA%E4%B8%AD%22%5D%0A%20%20AIR%20--%3E%20ACK%5B%22SIFS%20%E5%90%8E%20ACK%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有线链路预算是电缆长度；这里是距离、遮挡、干扰。交换机学有线 MAC；无线客户端经 AP 桥到有线侧，AP 是翻译，不是 WDM 模块。巨帧在无线上更易错，重传代价高，故常保持较小 MSDU。</p><p>容量课的 \\(C\\) 对时变信道是瞬间量，802.11 用 MCS 阶梯逼近。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 802.11ax 的 OFDMA 调度。MIMO 与速率自适应是下一课。后课默认：Wi‑Fi 数据面是 MAC 重传 + OFDM 比特加载。</p><p>不要把 Wi‑Fi 当蜂窝核心网：没有 RAN 切片，本课序后部才到 5G。</p><p>上一课留下的缺口在本课收口；「802.11 帧与 OFDM」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/mimo-rate-adaptation">MIMO 与速率自适应</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CA + ACK 补上无线不能可靠 CD 的缺口。</li><li>OFDM 用多子载波对抗多径 ISI。</li><li>链路 ACK 不取消 TCP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.11；Weinstein–Ebert；Kurose and Ross。</li></ul>',10))])}const u=o(c,[["render",C]]);export{S as __pageData,u as default};
